function r2(n) { return Math.round(Number(n) * 100) / 100; }
function calcularPropuesta(d) {
  const errores = [];
  const MODELOS = ['Corsair', 'Nautilus', 'Aviator', 'Navigator'];
  const inv = Number(d.inversion_total_mxn);
  if (!(inv > 0)) errores.push('inversion_total_mxn debe ser un número positivo');
  const iva = String(d.tratamiento_iva || '').toLowerCase();
  if (!iva.includes('antes')) errores.push('La inversión debe expresarse antes de IVA');
  const asig = Number(d.asignacion_mxn);
  const disp = Number(d.disponible_mxn);
  if (!(asig > 0)) errores.push('asignacion_mxn inválida');
  if (!(disp >= 0)) errores.push('disponible_mxn inválido');
  const ventasIn = d.ventas || {};
  const ventas = {};
  MODELOS.forEach((m) => {
    const v = ventasIn[m] !== undefined ? ventasIn[m] : ventasIn[m.toLowerCase()];
    ventas[m] = Number(v);
    if (!Number.isFinite(ventas[m])) errores.push('Falta venta 2025 de ' + m);
  });
  const mercado = Array.isArray(d.mercado) ? d.mercado : [];
  if (mercado.length !== 4) errores.push('Se esperaban 4 segmentos de mercado PMA; se recibieron ' + mercado.length);
  if (errores.length) return { ok: false, errores };

  const elegible = inv;
  const teorico = r2(elegible * 0.5);
  const apoyo = r2(Math.min(teorico, disp));
  const suficiente = disp >= teorico;
  const inversionAjustada = suficiente ? null : r2(2 * apoyo);
  const aportacionDistribuidor = suficiente ? r2(elegible - apoyo) : apoyo;
  const saldoProyectado = r2(disp - apoyo);

  const maxVenta = Math.max(...MODELOS.map((m) => ventas[m]));
  const fortaleza = MODELOS.filter((m) => ventas[m] === maxVenta);
  const norm = mercado.map((x) => ({
    modelo: String(x.modelo),
    categoria: x.categoria,
    volumen_2025: Number(x.volumen_2025),
    crecimiento_real_pct: Number(x.crecimiento_real_pct),
    penetracion_pct: Number(x.penetracion_pct)
  }));
  const positivos = norm.filter((x) => x.crecimiento_real_pct > 0);
  const maxCrec = positivos.length ? Math.max(...positivos.map((x) => x.crecimiento_real_pct)) : null;
  const oportunidad = positivos.filter((x) => x.crecimiento_real_pct === maxCrec);
  const opModelos = oportunidad.map((x) => x.modelo);
  const coinciden = fortaleza.length === 1 && opModelos.length === 1 && fortaleza[0].toLowerCase() === opModelos[0].toLowerCase();

  return {
    ok: true,
    errores: [],
    inversion_total_mxn: inv,
    inversion_elegible_mxn: elegible,
    apoyo_teorico_mxn: teorico,
    apoyo_lincoln_mxn: apoyo,
    aportacion_distribuidor_mxn: aportacionDistribuidor,
    asignacion_mxn: asig,
    saldo_disponible_actual_mxn: disp,
    saldo_proyectado_mxn: saldoProyectado,
    saldo_suficiente: suficiente,
    inversion_ajustada_mxn: inversionAjustada,
    requiere_aceptacion_ajuste: !suficiente,
    fortaleza: { modelos: fortaleza, ventas_2025: maxVenta, empate: fortaleza.length > 1 },
    oportunidad: { segmentos: oportunidad, empate: oportunidad.length > 1 },
    fortaleza_y_oportunidad_coinciden: coinciden,
    estado_aprobacion: 'PENDIENTE_APROBACION_HUMANA',
    modifica_presupuesto: false
  };
}

