const USUARIO_AUTORIZADO = "1000000001";
return $input.all().map((item,index)=>{
 const e=item.json,m=e.message;
 const usuario=String(m?.from?.id??""),chat=String(m?.chat?.id??"");
 const texto=typeof m?.text==="string"?m.text.trim():"";
 const autorizado=usuario===USUARIO_AUTORIZADO&&chat===USUARIO_AUTORIZADO&&m?.chat?.type==="private"&&m?.from?.is_bot===false;
 let ruta="PROCESAR",respuesta="",decision=null;
 if(!autorizado) ruta="NO_AUTORIZADO";
 else if(!texto){ruta="RESPONDER";respuesta="Envía tu solicitud como mensaje de texto.";}
 else if(texto.length>4000){ruta="RESPONDER";respuesta="El mensaje debe tener máximo 4000 caracteres.";}
 else if(/^\/(aprobar|rechazar)(?:@\w+)?(?:\s|$)/i.test(texto)){
  const c=texto.match(/^\/(aprobar|rechazar)(?:@\w+)?\s+(LIN-\d+-\d+)\s+([1-9]\d*)$/i);
  if(!c){ruta="RESPONDER";respuesta="Formato: /aprobar LIN-25-1 1 o /rechazar LIN-25-1 1. Incluye el folio y la versión recibidos.";}
  else {ruta="DECIDIR";decision={accion:c[1].toLowerCase(),caso_id:c[2].toUpperCase(),version:c[3],decision_id:String(e.update_id??"")};}
 }
 else if(/^\/(start|help)(?:@\w+)?(?:\s|$)/i.test(texto)){
 ruta="RESPONDER";respuesta="Asistente académico Lincoln. Envía distribuidor, formato del evento, modelo, fecha, inversión antes de IVA, asistentes, edades, NSE y objetivo. Para decidir usa /aprobar FOLIO VERSION o /rechazar FOLIO VERSION. Solo simulación; no se realizan pagos.";
 }
 else if(texto.startsWith("/")){ruta="RESPONDER";respuesta="Comando no reconocido. Usa /help.";}
 return {json:{canal:"telegram",modo:"SIMULADO",usuario,chat_id:chat,update_id:e.update_id??null,message_id:m?.message_id??null,solicitud:autorizado?texto:"",autorizado,ruta,respuesta,decision,limite_costo_usd:0.25,objetivo:"Evaluar una solicitud de apoyo para un evento"},pairedItem:{item:index}};
});

const original = $("Inicializar caso").first().json;
return $input.all().map((item,index)=>{
 let resultado;
 try { resultado=JSON.parse(item.json.output); } catch { throw new Error("La respuesta del orquestador no es JSON válido."); }
 if(!original.caso_id || resultado.caso_id!==original.caso_id) throw new Error("El folio del resultado no coincide con el caso original.");
 if(!["PENDIENTE_APROBACION","REQUIERE_ACLARACION","DETENIDO"].includes(resultado.estado)) throw new Error("Estado del caso no permitido.");
 if(original.modo!=="SIMULADO") throw new Error("Solo se registra modo SIMULADO.");
 if(original.canal==="telegram" && original.autorizado!==true) throw new Error("Usuario no autorizado.");
 const version=resultado.estado==="PENDIENTE_APROBACION"?"1":"0";
 if(version==="1" && (!Array.isArray(resultado.fuentes) || resultado.fuentes.length<3)) throw new Error("Propuesta sin referencias suficientes.");
 return {json:{caso_id:original.caso_id,usuario:String(original.usuario),estado:resultado.estado,version_propuesta:version,propuesta_json:JSON.stringify({caso_original:original,resultado,aprobacion_humana:false,modifica_presupuesto:false}),vence_en:new Date(Date.now()+30*60*1000).toISOString(),update_id:String(original.update_id??"manual"),decision_id:""},pairedItem:{item:index}};
});

const entrada=$("Validar entrada Telegram").first().json;
const d=entrada.decision;
if(entrada.autorizado!==true||entrada.ruta!=="DECIDIR"||entrada.modo!=="SIMULADO"||!d||!d.decision_id) throw new Error("Decisión no autorizada");
const filas=$input.all().map(i=>i.json).filter(r=>r.id!=null);
const base={chat_id:entrada.chat_id,usuario:entrada.usuario,aplicar:false,respuesta:"No se pudo aplicar la decisión. Revisa el folio y la versión."};
if(filas.length!==1) return [{json:{...base,respuesta:"El folio no existe o no es único. No se realizó ningún cambio."}}];
const r=filas[0];
if(r.caso_id!==d.caso_id||String(r.usuario)!==String(entrada.usuario)||String(r.version_propuesta)!==d.version) return [{json:base}];
if(r.estado!=="PENDIENTE_APROBACION"||r.decision_id) return [{json:{...base,respuesta:"El caso ya fue decidido o no está pendiente. No se realizó ningún cambio."}}];
const vence=Date.parse(r.vence_en);
if(!Number.isFinite(vence)) return [{json:{...base,respuesta:"El caso no tiene una vigencia válida. No se realizó ningún cambio."}}];
const vencido=Date.now()>=vence;
let p;try{p=JSON.parse(r.propuesta_json);}catch{throw new Error("Registro de propuesta inválido");}
if(p.caso_original?.modo!=="SIMULADO"||p.caso_original?.caso_id!==r.caso_id) throw new Error("Caso original no válido");
const estado=vencido?"VENCIDO":d.accion==="aprobar"?"APROBADO_SIMULADO":"RECHAZADO";
const registro={...p,aprobacion_humana:estado==="APROBADO_SIMULADO",modifica_presupuesto:false,decision:{accion:vencido?"vencimiento":d.accion,usuario:entrada.usuario,version:d.version,update_id:d.decision_id,fecha:new Date().toISOString()}};
return [{json:{...base,aplicar:true,id:r.id,caso_id:r.caso_id,version_propuesta:r.version_propuesta,estado,decision_id:d.decision_id,propuesta_json:JSON.stringify(registro),respuesta:vencido?"El caso venció. Solicita una nueva evaluación.":"Decisión registrada: "+estado+". Caso "+r.caso_id+", versión "+r.version_propuesta+". Simulación académica; no se realizan pagos ni cambios al presupuesto."}}];
